sudo mkdir -p {{NODE_DIR}}
sudo chown "$USER":"$USER" {{NODE_DIR}}
cd {{NODE_DIR}}
nano docker-compose.yml

https://{{PANEL_DOMAIN}} {
    encode
    reverse_proxy * http://remnawave:3000
}

:443 {
    tls internal
    respond 204
}

upstream remnawave {
    server remnawave:3000;
}

map $http_upgrade $connection_upgrade {
    default upgrade;
    "" close;
}

server {
    server_name {{PANEL_DOMAIN}};
    listen 443 ssl reuseport;
    listen [::]:443 ssl reuseport;
    http2 on;

    location / {
        proxy_http_version 1.1;
        proxy_pass http://remnawave;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
    }

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_timeout 1d;
    ssl_session_cache shared:MozSSL:10m;
    ssl_session_tickets off;
    ssl_certificate /etc/nginx/ssl/fullchain.pem;
    ssl_certificate_key /etc/nginx/ssl/privkey.key;
    ssl_trusted_certificate /etc/nginx/ssl/fullchain.pem;
}

server {
    listen 443 ssl default_server;
    listen [::]:443 ssl default_server;
    server_name _;
    ssl_reject_handshake on;
}

{
  "log": {
    "loglevel": "warning"
  },
  "dns": {
    "queryStrategy": "UseIPv4"
  },
  "inbounds": [
    {
      "tag": "VLESS_XHTTP_CDN",
      "listen": "127.0.0.1",
      "port": {{XHTTP_PORT}},
      "protocol": "vless",
      "settings": {
        "clients": [],
        "decryption": "none"
      },
      "sniffing": {
        "enabled": true,
        "destOverride": [
          "http",
          "tls",
          "quic"
        ]
      },
      "streamSettings": {
        "network": "xhttp",
        "security": "none",
        "xhttpSettings": {
          "mode": "packet-up",
          "path": "/",
          "extra": {
            "mode": "packet-up",
            "path": "/",
            "uplinkHTTPMethod": "GET",
            "xPaddingHeader": "X-Cache",
            "xPaddingKey": "_dc",
            "xPaddingMethod": "tokenish",
            "xPaddingObfsMode": true,
            "xPaddingPlacement": "queryInHeader",
            "uplinkDataPlacement": "header",
            "uplinkDataKey": "X-Request-Trace",
            "scMaxEachPostBytes": 24000,
            "scMinPostsIntervalMs": 10,
            "serverMaxHeaderBytes": 65536
          }
        }
      }
    }
  ],
  "outbounds": [
    {
      "tag": "DIRECT",
      "protocol": "freedom",
      "settings": {
        "domainStrategy": "UseIPv4"
      }
    },
    {
      "tag": "BLOCK",
      "protocol": "blackhole"
    }
  ],
  "routing": {
    "rules": [
      {
        "type": "field",
        "protocol": [
          "bittorrent"
        ],
        "outboundTag": "BLOCK"
      }
    ]
  }
}

server {
    listen 80;
    server_name {{ORIGIN_DOMAIN}};
    location ^~ /.well-known/acme-challenge/ { root /var/www/letsencrypt; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl;
    server_name {{ORIGIN_DOMAIN}};

    ssl_certificate     /etc/letsencrypt/live/{{ORIGIN_DOMAIN}}/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/{{ORIGIN_DOMAIN}}/privkey.pem;

    location / {
        proxy_pass http://127.0.0.1:{{XHTTP_PORT}};
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}

dig +short A {{ORIGIN_DOMAIN}}
dig +short CNAME {{CDN_DOMAIN}}
curl -Iv --max-time 15 https://{{CDN_DOMAIN}}/
